      const history = settings.enabled && settings.noticeVersion === NOTICE_VERSION ? await repository.readPrivateHistory(scope, 4, input.sessionId) : [];
      const currentMessages = Array.isArray(ctx.messages) ? ctx.messages : [];
      let analysis;
