test('Resposta adequada não custa uma reescrita adicional',async()=>{const {calls,provider}=fixture(['Em quais situações isso se repete?']);assert.equal((await provider.respond(payload)).text,'Em quais situações isso se repete?');assert.equal(calls.length,1)});
